struct Node { int value; Node* next; };

void pushFront(Node** head, int value) {}
bool removeFirst(Node** head, int value) { return false; }
int removeAll(Node** head, int value) { return 0; }
void skipUntil(const char** cursor, char stop) {}

solution.solution.cpp:
struct Node { int value; Node* next; };

void pushFront(Node** head, int value)
{
    *head = new Node{ value, *head };
}

bool removeFirst(Node** head, int value)
{
    Node** link{ head };
    while (*link && (*link)->value != value) link = &(*link)->next;
    if (!*link) return false;
    Node* dead{ *link };
    *link = dead->next;
    delete dead;
    return true;
}

int removeAll(Node** head, int value)
{
    int removed{ 0 };
    Node** link{ head };
    while (*link)
    {
        if ((*link)->value == value)
        {
            Node* dead{ *link };
            *link = dead->next;
            delete dead;
            ++removed;
        }
        else link = &(*link)->next;
    }
    return removed;
}

void skipUntil(const char** cursor, char stop)
{
    while (**cursor != '\0' && **cursor != stop) ++*cursor;
}

unitTests:
#include <vector>
static std::vector<int> values(const Node* n) { std::vector<int> v; for (; n; n = n->next) v.push_back(n->value); return v; }
static void freeAll(Node* n) { while (n) { Node* next{ n->next }; delete n; n = next; } }

TEST("pushFront changes the head") {
    Node* head{ nullptr };
    pushFront(&head, 3); pushFront(&head, 2); pushFront(&head, 1);
    CHECK_EQ(values(head), (std::vector<int>{ 1, 2, 3 }));
    freeAll(head);
}
TEST("removeFirst, including the head") {
    Node* head{ nullptr };
    for (int v : { 4, 7, 9, 7, 1 }) pushFront(&head, v);
    CHECK(removeFirst(&head, 7));
    CHECK_EQ(values(head), (std::vector<int>{ 1, 9, 7, 4 }));
    CHECK(removeFirst(&head, 1));
    CHECK_EQ(values(head), (std::vector<int>{ 9, 7, 4 }));
    CHECK(removeFirst(&head, 4));
    CHECK_EQ(values(head), (std::vector<int>{ 9, 7 }));
    CHECK(!removeFirst(&head, 42));
    freeAll(head);
    Node* empty{ nullptr };
    CHECK(!removeFirst(&empty, 1));
}
TEST("removeAll") {
    Node* head{ nullptr };
    for (int v : { 5, 5, 2, 5, 3, 5, 5 }) pushFront(&head, v);
    CHECK_EQ(removeAll(&head, 5), 5);
    CHECK_EQ(values(head), (std::vector<int>{ 3, 2 }));
    CHECK_EQ(removeAll(&head, 8), 0);
    CHECK_EQ(removeAll(&head, 3), 1);
    CHECK_EQ(removeAll(&head, 2), 1);
    CHECK(head == nullptr);
}
TEST("skipUntil moves the caller's cursor") {
    const char* text{ "key=value;next" };
    const char* cursor{ text };
    skipUntil(&cursor, '=');
    CHECK(cursor == text + 3);
    skipUntil(&cursor, '=');
    CHECK(cursor == text + 3);
    ++cursor;
    skipUntil(&cursor, ';');
    CHECK(cursor == text + 9);
    skipUntil(&cursor, '#');
    CHECK_EQ(*cursor, '\0');
}

